import{getLocale}from './i18n.js';
import{uiMessage,uiLeaf,uiSourceLeaf,uiSet,uiRaw,uiAttribute,uiAttributeAttrs,uiHtml,watchPracticeUi}from './practice-i18n.js';
const UMRAH_UI_KEYS=Object.freeze({"Умра":"umrahUi.title","Не удалось сохранить место урока":"umrahUi.saveFailed","Источники":"umrahUi.sources","ПУТЬ К ЗАПОВЕДНОЙ МЕЧЕТИ":"umrahUi.eyebrow","От намерения до завершения":"umrahUi.heroTitle","Короткие уроки, наглядные схемы и памятка для поездки.":"umrahUi.intro","Повторить урок":"umrahUi.repeatLesson","Начать · 10 шагов":"umrahUi.startTen","Урок пройден":"umrahUi.lessonDone","Разделы Умры":"umrahUi.sections","История Умры":"umrahUi.history","Памятка паломника":"umrahUi.tips","Имамы Мекки и Медины":"umrahUi.imams","Все этапы":"umrahUi.allSteps","Порядок обрядов — по хадисам и руководству Министерства хаджа и Умры.":"umrahUi.orderSource","Переход по уроку":"umrahUi.lessonNavigation","К разделу":"umrahUi.backSection","Завершить урок":"umrahUi.finishLesson","Далее":"umrahUi.next","К уроку Умры":"umrahUi.backLesson","Что пригодится в дороге и в мечети.":"umrahUi.travelIntro","Открыть Nusuk":"umrahUi.openNusuk","Урок завершён":"umrahUi.lessonComplete","Порядок Умры изучен":"umrahUi.orderLearned","Вы можете повторить любой этап или открыть памятку перед поездкой.":"umrahUi.completeHint","К разделу Умры":"umrahUi.backUmrah","Записи официального портала двух святынь.":"umrahUi.portalIntro","Мечеть":"umrahUi.mosque","Мекка":"umrahUi.mecca","Медина":"umrahUi.medina","Месяц":"umrahUi.month","Дата":"umrahUi.date","Нет данных":"umrahUi.noData","Время Мекки и Медины · UTC+3":"umrahUi.saudiTime","Джума":"umrahUi.jumuah","Не опубликовано":"umrahUi.notPublished","Даты пока не опубликованы":"umrahUi.noDates","Для этого месяца на официальном портале нет записей. Выберите другой месяц или откройте источник.":"umrahUi.noDatesHint","проверьте свежие записи в источнике":"umrahUi.checkSource","Официальный портал":"umrahUi.officialPortal","Загружаем опубликованные записи…":"umrahUi.loading","Не удалось загрузить записи. Подключитесь к интернету и попробуйте снова.":"umrahUi.loadFailed","Знания":"nav.knowledge","Назад":"common.back","Повторить":"common.retry","Фаджр":"home.fajr","Зухр":"home.dhuhr","Аср":"home.asr","Магриб":"home.maghrib","Иша":"home.isha"});
const umrahArtwork=key=>umrahIllustration(key).replace('<svg ','<svg lang="ru" translate="no" ');
let stopUmrahLanguage=()=>{};
import{actionIcon,actionLabel}from './action-icons.js';
import{read,write}from './storage.js';
import{esc,toast}from './ui.js';
import{UMRAH_EDITION,umrahSources,umrahHistory,umrahSteps,pilgrimTips,validUmrahProgress,umrahRoute}from './umrah-content.js';
import{umrahIllustration}from './umrah-illustrations.js';
import{scheduleSources,schedulePrayers,imamLabel,saudiDay,scheduleTime,validScheduleMonth,validScheduleDay,validateHaramainSchedule,scheduleForDay,scheduleDays}from './haramain-schedule.js';
let generation=0,controller=null,snapshot=null;
const saved=()=>{const value=read('umrah-progress',null);return validUmrahProgress(value)?value:null};
const link=(view,label)=>`<a class="umrah-link" href="#umrah?view=${view}">${uiSourceLeaf(label,UMRAH_UI_KEYS)}${actionIcon('next')}</a>`;
const sources=refs=>`<details class="umrah-sources"><summary data-i18n="umrahUi.sources">Источники</summary>${refs.map(id=>umrahSources[id]).filter(Boolean).map(source=>`<a lang="ru" translate="no" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.label)} ${actionIcon('external')}</a>`).join('')}</details>`;
const figure=step=>`<figure lang="ru" translate="no">${umrahArtwork(step.image)}<figcaption lang="ru" translate="no">${esc(step.caption)}</figcaption></figure>`;
const head=(title,back='#umrah',label='Умра')=>`<header class="umrah-head"><a class="umrah-back" href="${back}"><span aria-hidden="true">‹</span> ${uiSourceLeaf(label,UMRAH_UI_KEYS)}</a><h1${Object.hasOwn(UMRAH_UI_KEYS,title)?'':' lang="ru" translate="no"'}>${uiSourceLeaf(title,UMRAH_UI_KEYS)}</h1></header>`;
function save(index,complete=saved()?.complete||false){if(!write('umrah-progress',{edition:UMRAH_EDITION,index,complete}))toast(uiMessage('umrahUi.saveFailed','Не удалось сохранить место урока'))}
function overview(){const progress=saved();return `${head('Умра','#knowledge','Знания')}<div class="umrah-hero">${umrahArtwork('arrival')}<span class="knowledge-eyebrow" data-i18n="umrahUi.eyebrow">ПУТЬ К ЗАПОВЕДНОЙ МЕЧЕТИ</span><h2 data-i18n="umrahUi.heroTitle">От намерения до завершения</h2><p data-i18n="umrahUi.intro">Короткие уроки, наглядные схемы и памятка для поездки.</p><a class="button" href="#umrah?step=${progress&&!progress.complete?umrahSteps[progress.index].id:'prepare'}">${progress?progress.complete?uiLeaf('umrahUi.repeatLesson','Повторить урок'):uiLeaf('umrahUi.continueStep','Продолжить · шаг {step}',{step:progress.index+1}):uiLeaf('umrahUi.startTen','Начать · 10 шагов')}</a>${progress?.complete?'<span class="umrah-done" data-i18n="umrahUi.lessonDone">Урок пройден</span>':''}</div><nav class="umrah-links" aria-label="Разделы Умры" data-i18n-aria-label="umrahUi.sections">${link('history','История Умры')}${link('tips','Памятка паломника')}${link('imams','Имамы Мекки и Медины')}</nav><details class="umrah-curriculum"><summary><span data-i18n="umrahUi.allSteps">Все этапы</span> <span>10</span></summary>${umrahSteps.map((row,index)=>`<a href="#umrah?step=${row.id}"><span>${String(index+1).padStart(2,'0')}</span><span lang="ru" translate="no">${esc(row.title)}</span></a>`).join('')}</details><p class="umrah-footnote" data-i18n="umrahUi.orderSource">Порядок обрядов — по хадисам и руководству Министерства хаджа и Умры.</p>`}
function lesson(index){const step=umrahSteps[index];save(index);return `${head(step.chapter)}<div class="umrah-progress" ${uiAttributeAttrs('aria-label','umrahUi.stepPosition',{step:index+1,total:umrahSteps.length})}><span>${uiLeaf('umrahUi.stepPosition','Шаг {step} из {total}',{step:index+1,total:umrahSteps.length})}</span><span>${Math.round((index+1)/umrahSteps.length*100)}%</span><div><i style="width:${(index+1)/umrahSteps.length*100}%"></i></div></div><article class="umrah-lesson">${figure(step)}<h2 lang="ru" translate="no">${esc(step.title)}</h2>${step.paragraphs.map(p=>`<p lang="ru" translate="no">${esc(p)}</p>`).join('')}${step.formula?`<div class="umrah-formula"><p class="umrah-arabic" lang="ar" dir="rtl">${esc(step.formula.arabic)}</p><p lang="ru" translate="no">${esc(step.formula.transcription)}</p><p class="umrah-meaning" lang="ru" translate="no">${esc(step.formula.meaning)}</p></div>`:''}${step.note?`<p class="umrah-note" lang="ru" translate="no">${esc(step.note)}</p>`:''}${step.detail?`<details class="umrah-detail"><summary lang="ru" translate="no">${esc(step.detail.title)}</summary><p lang="ru" translate="no">${esc(step.detail.text)}</p></details>`:''}${sources(step.refs)}</article><nav class="umrah-step-nav" aria-label="Переход по уроку" data-i18n-aria-label="umrahUi.lessonNavigation">${index?`<a class="button secondary" href="#umrah?step=${umrahSteps[index-1].id}" data-i18n="common.back">Назад</a>`:'<a class="button secondary" href="#umrah" data-i18n="umrahUi.backSection">К разделу</a>'}${index<umrahSteps.length-1?`<a class="button" href="#umrah?step=${umrahSteps[index+1].id}">${uiLeaf('umrahUi.next','Далее')} ${actionIcon('next')}</a>`:'<a id="umrah-complete" class="button" href="#umrah?view=complete" data-i18n="umrahUi.finishLesson">Завершить урок</a>'}</nav>`}
function history(){return `${head('История Умры')}${umrahHistory.map((row,index)=>`<article class="umrah-story">${umrahArtwork(['arrival','safa','miqat'][index])}<h2 lang="ru" translate="no">${esc(row.title)}</h2><p lang="ru" translate="no">${esc(row.text)}</p>${sources(row.refs)}</article>`).join('')}${link('home','К уроку Умры')}`.replace('#umrah?view=home','#umrah')}
function tips(){return `${head('Памятка паломника')}<p class="umrah-intro" data-i18n="umrahUi.travelIntro">Что пригодится в дороге и в мечети.</p>${pilgrimTips.map((row,index)=>`<details class="umrah-tip" ${index===0?'open':''}><summary lang="ru" translate="no">${esc(row.title)}</summary><div><p lang="ru" translate="no">${esc(row.text)}</p>${sources(row.refs)}</div></details>`).join('')}<a class="button secondary umrah-official" href="${umrahSources.nusuk.url}" target="_blank" rel="noopener noreferrer">${uiLeaf('umrahUi.openNusuk','Открыть Nusuk')} ${actionIcon('external')}</a>`}
function complete(){return `${head('Урок завершён')}<div class="umrah-hero">${umrahArtwork('finish')}<h2 data-i18n="umrahUi.orderLearned">Порядок Умры изучен</h2><p data-i18n="umrahUi.completeHint">Вы можете повторить любой этап или открыть памятку перед поездкой.</p><a class="button" href="#umrah?view=tips" data-i18n="umrahUi.tips">Памятка паломника</a><a class="umrah-back" href="#umrah" data-i18n="umrahUi.backUmrah">К разделу Умры</a></div>`}
function monthTitle(month){return new Intl.DateTimeFormat(getLocale(),{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(month+'-01T12:00:00Z'))}
function scheduleHeader(){return `${head('Имамы Мекки и Медины')}<p class="umrah-intro" data-i18n="umrahUi.portalIntro">Записи официального портала двух святынь.</p>`}
function scheduleView(route,data){
 const today=saudiDay(Date.now()),month=validScheduleMonth(route.month)?route.month:today.slice(0,7);
 const available=[...new Set([today.slice(0,7),month,...data.rows.map(row=>row.day.slice(0,7))])].sort();
 const days=scheduleDays(data,route.mosque,month),day=validScheduleDay(route.day)&&days.includes(route.day)?route.day:days.includes(today)?today:days.at(-1)||month+'-01';
 const rows=scheduleForDay(data,route.mosque,day);
 const stale=Date.now()-Date.parse(data.fetchedAt)>2*86400000;
 const dateLabel=new Intl.DateTimeFormat(getLocale(),{timeZone:'Asia/Riyadh',day:'numeric',month:'long'}).format(new Date(day+'T12:00:00+03:00'));
 return `${scheduleHeader()}<div class="umrah-mosques" role="group" aria-label="Мечеть" data-i18n-aria-label="umrahUi.mosque">${[['mecca','Мекка'],['madinah','Медина']].map(([id,label])=>`<a class="${route.mosque===id?'active':''}" ${route.mosque===id?'aria-current="true"':''} href="#umrah?view=imams&mosque=${id}&month=${month}">${uiSourceLeaf(label,UMRAH_UI_KEYS)}</a>`).join('')}</div><div class="umrah-schedule-filters"><label><span data-i18n="umrahUi.month">Месяц</span><select id="umrah-month">${available.map(value=>`<option value="${value}" ${month===value?'selected':''} data-umrah-month="${value}">${esc(monthTitle(value))}</option>`).join('')}</select></label><label><span data-i18n="umrahUi.date">Дата</span><select id="umrah-day" ${days.length?'':'disabled'}>${days.length?days.map(value=>`<option value="${value}" ${day===value?'selected':''}>${Number(value.slice(8))}</option>`).join(''):'<option data-i18n="umrahUi.noData">Нет данных</option>'}</select></label></div><p class="umrah-schedule-note" data-i18n="umrahUi.saudiTime">Время Мекки и Медины · UTC+3</p><section class="umrah-schedule-list" ${uiAttributeAttrs('aria-label','umrahUi.scheduleOn',{date:dateLabel})} data-umrah-schedule-day="${day}">${rows.length?`<h2 data-umrah-date="${day}">${esc(dateLabel)}</h2>${Object.entries(schedulePrayers).map(([key,name])=>{const row=rows.find(value=>value.prayer===key),jumuah=key==='dhuhr'&&new Date(day+'T12:00:00Z').getUTCDay()===5;return `<div class="umrah-schedule-row"><div><strong>${uiSourceLeaf(jumuah?'Джума':name,UMRAH_UI_KEYS)}</strong><span dir="auto">${row?'<span lang="ru" translate="no">'+esc(imamLabel(row.imam))+'</span>':uiLeaf('umrahUi.notPublished','Не опубликовано')}</span></div><time>${row?scheduleTime(row.at):'—'}</time></div>`}).join('')}`:'<div class="umrah-schedule-empty"><h2 data-i18n="umrahUi.noDates">Даты пока не опубликованы</h2><p data-i18n="umrahUi.noDatesHint">Для этого месяца на официальном портале нет записей. Выберите другой месяц или откройте источник.</p></div>'}</section><p class="umrah-footnote">${uiLeaf('umrahUi.datesNotice','Отображаются только опубликованные записи, а не предполагаемые назначения. Доступные даты в выбранном месяце: {count}.',{count:days.length})}</p><p class="umrah-snapshot-date ${stale?'stale':''}"><span data-umrah-data-at="${esc(data.fetchedAt)}">${esc(uiMessage('umrahUi.dataFrom','Данные от {date}',{date:new Intl.DateTimeFormat(getLocale(),{timeZone:'Asia/Riyadh',day:'numeric',month:'long',year:'numeric'}).format(new Date(data.fetchedAt))}))}</span>${stale?' · '+uiLeaf('umrahUi.checkSource','проверьте свежие записи в источнике'):''}</p><a class="button secondary umrah-official" href="${scheduleSources[route.mosque]}" target="_blank" rel="noopener noreferrer">${uiLeaf('umrahUi.officialPortal','Официальный портал')} ${actionIcon('external')}</a>`;
}
function bindSchedule(host,route){host.querySelector('#umrah-month')?.addEventListener('change',event=>{location.hash='umrah?view=imams&mosque='+route.mosque+'&month='+event.target.value});host.querySelector('#umrah-day')?.addEventListener('change',event=>{location.hash='umrah?view=imams&mosque='+route.mosque+'&month='+host.querySelector('#umrah-month').value+'&day='+event.target.value})}
export function stopUmrah(){stopUmrahLanguage();stopUmrahLanguage=()=>{};generation++;controller?.abort();controller=null;document.body.classList.remove('umrah-focus')}
export async function showUmrah(host){
 stopUmrah();const request=generation,hash=location.hash,route=umrahRoute(hash);
 document.body.classList.toggle('umrah-focus',route.view==='lesson');
 host.innerHTML='<section class="umrah-page"></section>';const page=host.querySelector('.umrah-page');function paint(html){stopUmrahLanguage();page.innerHTML=uiHtml(html);stopUmrahLanguage=watchPracticeUi(page,()=>updateScheduleDates(page));}
 if(route.view==='lesson'){paint(lesson(route.step));page.querySelector('#umrah-complete')?.addEventListener('click',()=>save(umrahSteps.length-1,true));return}
 if(route.view==='history'){paint(history());return}
 if(route.view==='tips'){paint(tips());return}
 if(route.view==='complete'){paint(complete());return}
 if(route.view!=='imams'){paint(overview());return}
 paint(scheduleHeader()+'<p role="status" data-i18n="umrahUi.loading">Загружаем опубликованные записи…</p>');
 const pending=new AbortController();controller=pending;
 const timer=setTimeout(()=>pending.abort(),10000);
 const current=()=>request===generation&&hash===location.hash;
 try{
  if(!snapshot){const response=await fetch('./data/haramain-schedule.json',{signal:pending.signal,cache:'no-cache'});if(!response.ok)throw Error('Schedule unavailable');snapshot=validateHaramainSchedule(await response.json())}
  if(!current())return;
  paint(scheduleView(route,snapshot));bindSchedule(page,route);
 }catch{if(current()){paint(scheduleHeader()+`<p role="status" data-i18n="umrahUi.loadFailed">Не удалось загрузить записи. Подключитесь к интернету и попробуйте снова.</p><button class="button secondary" id="umrah-retry" data-i18n="common.retry">Повторить</button><a class="umrah-link" href="${scheduleSources[route.mosque]}" target="_blank" rel="noopener noreferrer">${uiLeaf('umrahUi.officialPortal','Официальный портал')} ${actionIcon('external')}</a>`);page.querySelector('#umrah-retry').onclick=()=>showUmrah(host)}}finally{clearTimeout(timer);if(controller===pending)controller=null}
}

function updateScheduleDates(page){for(const node of page.querySelectorAll('[data-umrah-month]'))uiRaw(node,monthTitle(node.dataset.umrahMonth));for(const node of page.querySelectorAll('[data-umrah-date]'))uiRaw(node,new Intl.DateTimeFormat(getLocale(),{timeZone:'Asia/Riyadh',day:'numeric',month:'long'}).format(new Date(node.dataset.umrahDate+'T12:00:00+03:00')));for(const node of page.querySelectorAll('[data-umrah-schedule-day]'))uiAttribute(node,'aria-label','umrahUi.scheduleOn','Расписание на {date}',{date:new Intl.DateTimeFormat(getLocale(),{timeZone:'Asia/Riyadh',day:'numeric',month:'long'}).format(new Date(node.dataset.umrahScheduleDay+'T12:00:00+03:00'))});for(const node of page.querySelectorAll('[data-umrah-data-at]'))uiSet(node,'umrahUi.dataFrom','Данные от {date}',{date:new Intl.DateTimeFormat(getLocale(),{timeZone:'Asia/Riyadh',day:'numeric',month:'long',year:'numeric'}).format(new Date(node.dataset.umrahDataAt))});}
